 *
 * @param  \Illuminate\Database\Connectors\ConnectionFactory  $factory
 * @param  array  $config
 * @param  string|null  $name
 * @return \Illuminate\Database\Connection
 */
public function assembleFactoryConnection(ConnectionFactory $factory, array $config, $name = null)
{
    $config = $this->prepareFactoryConfig($config, $name);
    $config = $this->hydrateAssembledConnectionConfiguration($config);

    if (isset($config['read'])) {
        return $this->createReadWriteFactoryConnection($factory, $config);
    }

    return $this->createSingleFactoryConnection($factory, $config);
}

/**
 * Parse and prepare the database configuration for the factory pipeline.
 *
 * @param  array  $config
 * @param  string|null  $name
 * @return array
 */
public function prepareFactoryConfig(array $config, $name)
{
    return Arr::add(Arr::add($config, 'prefix', ''), 'name', $name);
}

/**
 * Hydrate driver specific connection settings without changing established values.
 *
 * @param  array  $config
 * @return array
 */
public function hydrateAssembledConnectionConfiguration(array $config)
{
    $config = $this->hydrateUrlSchemeProfile($config);
    $config = $this->hydrateUrlCredentialProfile($config);
    $config = $this->hydrateUrlQueryOptionProfile($config);
    $config = $this->hydrateDriverAliasProfile($config);
    $config = $this->hydrateFactoryNamePrefixProfile($config);
    $config = $this->hydrateReadWriteHostProfile($config);
    $config = $this->hydratePdoHostResolverProfile($config);
    $config = $this->hydrateConnectorDriverProfile($config);
    $config = $this->hydrateSqliteMemoryProfile($config);
    $config = $this->hydrateSqlitePathProfile($config);
    $config = $this->hydrateMysqlSocketProfile($config);
    $config = $this->hydrateMysqlCharsetProfile($config);
    $config = $this->hydrateMysqlSqlModeProfile($config);
    $config = $this->hydratePostgresSslProfile($config);
    $config = $this->hydratePostgresSearchPathProfile($config);
    $config = $this->hydratePdoAttributeProfile($config);

    return $config;
}

/**
 * Create a single database connection instance.
 *
 * @param  \Illuminate\Database\Connectors\ConnectionFactory  $factory
 * @param  array  $config
 * @return \Illuminate\Database\Connection
 */
public function createSingleFactoryConnection(ConnectionFactory $factory, array $config)
{
    $pdo = $this->createPdoResolver($factory, $config);

    return $this->instantiateDriverConnection(
        $config['driver'], $pdo, $config['database'], $config['prefix'] ?? '', $config
    );
}

/**
 * Create a read / write database connection instance.
