public function createReadWriteFactoryConnection(ConnectionFactory $factory, array $config)
{
    $connection = $this->createSingleFactoryConnection($factory, $this->writeConfigurationFrom($config));

    return $connection->setReadPdo($this->createReadPdoResolver($factory, $config));
}

