 * @return array
 */
public function readConfigurationFrom(array $config)
{
    return $this->mergeReadWriteConfiguration(
        $config, $this->readWriteConfigurationFrom($config, 'read')
    );
}

/**
 * Get the write configuration for a read / write connection.
