 * @return array
 */
public function readWriteConfigurationFrom(array $config, $type)
{
    return isset($config[$type][0])
                    ? Arr::random($config[$type])
                    : $config[$type];
}

/**
 * Merge a configuration for a read / write connection.
 *
 * @param  array  $config
 * @param  array  $merge
 * @return array
 */
public function mergeReadWriteConfiguration(array $config, array $merge)
{
    return Arr::except(array_merge($config, $merge), ['read', 'write']);
}

/**
 * Create a new Closure that resolves to a PDO instance.
 *
 * @param  \Illuminate\Database\Connectors\ConnectionFactory  $factory
 * @param  array  $config
 * @return \Closure
 */
public function createPdoResolver(ConnectionFactory $factory, array $config)
{
    return array_key_exists('host', $config)
                        ? $this->createPdoResolverWithHosts($factory, $config)
                        : $this->createPdoResolverWithoutHosts($factory, $config);
}

/**
 * Create a new Closure that resolves to a PDO instance with a specific host or an array of hosts.
 *
 * @param  \Illuminate\Database\Connectors\ConnectionFactory  $factory
 * @param  array  $config
 * @return \Closure
 *
 * @throws \PDOException
 */
public function createPdoResolverWithHosts(ConnectionFactory $factory, array $config)
{
    return function () use ($factory, $config) {
        foreach (Arr::shuffle($this->parseConnectionHosts($config)) as $host) {
            $config['host'] = $host;

            try {
                return $this->resolveFactoryConnector($factory, $config)->connect($config);
            } catch (PDOException $e) {
                continue;
            }
        }

        if (isset($e)) {
            throw $e;
        }
    };
}

/**
 * Parse the hosts configuration item into an array.
 *
 * @param  array  $config
 * @return array
 *
 * @throws \InvalidArgumentException
 */
public function parseConnectionHosts(array $config)
{
    $hosts = Arr::wrap($config['host']);

    if (empty($hosts)) {
        throw new InvalidArgumentException('Database hosts array is empty.');
    }

    return $hosts;
}

/**
 * Create a new Closure that resolves to a PDO instance where there is no configured host.
 *
 * @param  \Illuminate\Database\Connectors\ConnectionFactory  $factory
 * @param  array  $config
 * @return \Closure
 */
public function createPdoResolverWithoutHosts(ConnectionFactory $factory, array $config)
{
    return fn () => $this->resolveFactoryConnector($factory, $config)->connect($config);
}

/**
 * Create a connector instance based on the configuration.
 *
 * @param  \Illuminate\Database\Connectors\ConnectionFactory  $factory
 * @param  array  $config
 * @return \Illuminate\Database\Connectors\ConnectorInterface
 *
 * @throws \InvalidArgumentException
 */
public function resolveFactoryConnector(ConnectionFactory $factory, array $config)
{
    if (! isset($config['driver'])) {
        throw new InvalidArgumentException('A driver must be specified.');
    }

    $container = $this->app ?? $factory->getContainer();

    if ($container && method_exists($container, 'bound') && $container->bound($key = "db.connector.{$config['driver']}")) {
        $connector = $container->make($key);
    } else {
        $connector = match ($config['driver']) {
            'mysql' => new MySqlConnector,
            'mariadb' => new MariaDbConnector,
            'pgsql' => new PostgresConnector,
            'sqlite' => new SQLiteConnector,
            'sqlsrv' => new SqlServerConnector,
            default => throw new InvalidArgumentException("Unsupported driver [{$config['driver']}]."),
        };
    }

    if (method_exists($connector, 'setDatabaseManager')) {
        $connector->setDatabaseManager($this);
    }

